do $$ declare item jsonb; prop jsonb; target_batch uuid; target_control uuid; ledger public.daily_controls%rowtype; part public.daily_control_participants%rowtype; expected uuid[]; actual uuid[]; num integer; begin
 for item in select value from association_plan cross join lateral jsonb_array_elements(data) loop
 target_batch:=(item->>'batch_id')::uuid;target_control:=(item->>'control_id')::uuid;
 perform 1 from public.ninja_operation_batches where id=target_batch and accounting_status<>'committed' for update;
 if not found then raise exception 'BATCH_CHANGED: %',target_batch; end if;
 select * into strict ledger from public.daily_controls where id=target_control for update;
 select array_agg(value::uuid order by value::uuid) into expected from jsonb_array_elements_text(item->'accounts');
 select array_agg(account_id order by account_id) into actual from public.daily_control_participants where daily_control_id=target_control;
 if expected is distinct from actual or ledger.operating_result_cents<>(item->>'result_cents')::bigint or (select sum(allocated_result_cents) from public.daily_control_participants where daily_control_id=target_control)<>ledger.operating_result_cents then raise exception 'CONTROL_PROOF_CHANGED: %',target_control; end if;
 if exists(select 1 from public.ninja_operation_batches where daily_control_id=target_control and id<>target_batch and accounting_status='committed') then raise exception 'CONTROL_ALREADY_MATCHED'; end if;
 for prop in select value from jsonb_array_elements(item->'sessions') loop
 select * into strict part from public.daily_control_participants where daily_control_id=target_control and account_id=(prop->>'account')::uuid;
 if not exists(select 1 from public.ninja_operation_probe_sessions s join public.ninja_account_links l on l.connector_id=s.connector_id and l.connection_name=s.connection_name and l.external_account_name=s.account_name where s.id=(prop->>'session')::bigint and l.account_id=part.account_id and s.status='closed' and l.first_seen_at<=s.opened_at and (l.closed_at is null or l.closed_at>=s.opened_at)) then raise exception 'SESSION_LINK_PROOF_CHANGED'; end if;
 insert into public.ninja_operation_batch_members(batch_id,session_id,account_id,role,allocated_broker_result_cents) values(target_batch,(prop->>'session')::bigint,part.account_id,'prop',part.allocated_result_cents) on conflict(batch_id,session_id) do update set account_id=excluded.account_id,role='prop',allocated_broker_result_cents=excluded.allocated_broker_result_cents;
 end loop;
 update public.ninja_operation_batches set accounting_status='committed',accounting_mode='active',accounting_blocking_reason=null,daily_control_id=target_control,accounting_period_id=ledger.period_id,accounting_company_id=ledger.company_id,accounting_phase=ledger.phase,context_prop_count=cardinality(expected),distributed_cents=ledger.operating_result_cents,rounding_difference_cents=0,updated_at=now() where id=target_batch;
 insert into public.audit_events(actor_user_id,entity_table,entity_id,action,current_data,reason) values('f2f5f816-ec4f-46e1-b216-5267aeadc635','ninja_operation_batches',target_batch,'legacy_burn_existing_control_linked_20261117',jsonb_build_object('daily_control_id',target_control,'accounts',expected,'financial_entries_added',0),'Coincidencia única de titular, fecha, resultado y grupo completo de cuentas; vínculo de telemetría recuperado sin duplicar contabilidad.');
 end loop;
end$$;
set constraints all immediate;
select count(*) as vinculaciones from public.audit_events where action='legacy_burn_existing_control_linked_20261117';
rollback;
